// Un solo WhatsApp por persona aunque haya hecho varios clics
const nacional = (tel) => {
  let d = String(tel || '').replace(/\D/g, '');
  if (d.startsWith('54')) d = d.slice(2);
  if (d.startsWith('9')) d = d.slice(1);
  if (d.startsWith('0')) d = d.slice(1);
  return d;
};
const grupos = {};
for (const { json: l } of $input.all()) {
  const nac = nacional(l.buyer_phone);
  if (nac.length < 10) continue;
  const key = nac.slice(-8);
  (grupos[key] = grupos[key] || []).push({ ...l, nac });
}
return Object.values(grupos).map(leads => {
  const ultimo = leads[leads.length - 1];
  const nombre = String(ultimo.buyer_nombre || '').trim();
  return { json: {
    ids_sql: leads.map(l => `'${l.id}'`).join(','),
    ml_lead_id: ultimo.id,
    telefono: '+549' + ultimo.nac.slice(-10),
    nombre_pila: nombre.split(' ')[0] || nombre,
    nombre,
    email: ultimo.buyer_email || '-',
    // el template ya dice "NISSAN {{2}}": se saca "Nuevo Nissan"/"Nissan" del titulo
    modelo: String(ultimo.item_titulo || '').replace(/^\s*(nuevo\s+)?nissan\s+/i, '').trim()
  } };
});

// Concesionario: se deduce la ciudad por la característica del celular.
// AMBA (11 y 2xx del conurbano) o desconocida -> '' (el matcher elige una sucursal CABA, como hoy).
const CARACTERISTICAS = {
  '2901': 'Ushuaia', '2964': 'Río Grande', '2966': 'Comodoro Rivadavia', '2920': 'Neuquén', '294': 'Neuquén',
  '2954': 'Santa Rosa', '2302': 'General Pico', '3564': 'San Francisco', '3492': 'Rafaela', '3462': 'Venado Tuerto',
  '2284': 'Olavarría', '2324': 'Mercedes', '2477': 'Pergamino', '2392': 'Trenque Lauquen', '2227': 'Lobos',
  '3489': 'Campana', '230': 'Pilar', '291': 'Bahía Blanca', '223': 'Mar del Plata', '236': 'Junín', '336': 'San Nicolás',
  '362': 'Resistencia', '364': 'Roque Saenz Peña', '370': 'Resistencia', '280': 'Trelew', '297': 'Comodoro Rivadavia',
  '351': 'Córdoba', '353': 'Villa María', '379': 'Corrientes', '343': 'Paraná', '345': 'Concordia',
  '261': 'Godoy Cruz', '260': 'San Rafael', '266': 'Godoy Cruz', '376': 'Posadas', '299': 'Neuquén', '264': 'San Juan',
  '342': 'Santa Fe', '341': 'Rosario', '381': 'Yerba Buena', '387': 'Yerba Buena', '388': 'Yerba Buena',
  '385': 'Yerba Buena', '383': 'Yerba Buena', '380': 'Yerba Buena'
};
const nacional = (tel) => {
  let d = String(tel || '').replace(/\D/g, '');
  if (d.startsWith('54')) d = d.slice(2);
  if (d.startsWith('9')) d = d.slice(1);
  if (d.startsWith('0')) d = d.slice(1);
  return d;
};
const ciudad = (nac) => {
  for (const len of [4, 3]) { const c = CARACTERISTICAS[nac.slice(0, len)]; if (c) return c; }
  return '';
};
const dniDeCuit = (cuit) => { const d = String(cuit || '').replace(/\D/g, ''); return d.length === 11 ? d.slice(2, 10) : '-'; };

// Nissan: un solo lead por persona, con la última publicación consultada (vienen ordenados por received_at).
// Todos los clics de la persona viajan en ml_lead_ids y quedan marcados como enviados.
const grupos = new Map();
for (const { json: l } of $input.all()) {
  const nac = nacional(l.buyer_phone);
  const key = nac.length >= 10 ? nac.slice(-8) : l.id;
  const g = grupos.get(key) || { ids: [], ultimo: null, nac };
  g.ids.push(l.id);
  g.ultimo = l;
  grupos.set(key, g);
}

// Motivo de la carga automática. El WhatsApp de cierre solo va a quien recibió el template y no contestó.
const MOTIVO = {
  template_sent: 'El cliente no respondió el WhatsApp en 1 hora',
  template_error: 'No se pudo enviar el WhatsApp; se requiere contacto desde el concesionario',
  in_conversation: 'El cliente conversó con el asesor virtual pero la conversación no se cerró'
};

return [...grupos.values()].map(({ ids, ultimo: l, nac }) => {
  const tieneTel = nac.length >= 10;
  const nombre = String(l.buyer_nombre || '').trim();
  const motivo = !tieneTel ? 'El lead no tiene celular' : (MOTIVO[l.status] || MOTIVO.template_sent);
  return { json: {
    goodLead: 'true',
    idConversation: '',
    number: tieneTel ? '+549' + nac.slice(-10) : '',
    name: nombre,
    pago: 'No especifica',
    usado: 'No especifica',
    interes: 'cold',
    productoInteres: l.item_titulo || '',
    resumen: `Lead de Mercado Libre (publicación ${l.item_id}: ${l.item_titulo}). ${motivo}; se deriva automáticamente.`,
    dni: dniDeCuit(l.buyer_cuit),
    email: l.buyer_email || '-',
    sucursal: tieneTel ? ciudad(nac) : '',
    ml_lead_ids: ids.join(','),
    nombre_pila: nombre.split(' ')[0] || nombre,
    enviar_whatsapp: tieneTel && l.status === 'template_sent'
  } };
});

const b = $input.first().json.body || {};
const d = String(b.phone || b.from || '').replace(/\D/g, '');
return [{ json: { sufijo: d.length >= 8 ? d.slice(-8) : '' } }];

const leads = $input.all().map(i => i.json).filter(l => l.id);
if (!leads.length) return [{ json: { found: false, ml_caso: 'sin_datos_ml' } }];
const ultimo = leads[leads.length - 1];
let d = String(ultimo.buyer_phone || '').replace(/\D/g, '');
if (d.startsWith('54')) d = d.slice(2);
if (d.startsWith('9')) d = d.slice(1);
if (d.startsWith('0')) d = d.slice(1);
const cuit = String(ultimo.buyer_cuit || '').replace(/\D/g, '');
return [{ json: {
  found: true,
  ml_caso: leads.some(l => l.status === 'template_sent') ? 'template' : 'dos_clics',
  ml_lead_ids: leads.map(l => l.id).join(','),
  ids_sql: leads.map(l => `'${l.id}'`).join(','),
  ml_nombre: String(ultimo.buyer_nombre || '').trim(),
  ml_email: ultimo.buyer_email || '-',
  ml_phone: d.length >= 10 ? '+549' + d.slice(-10) : '-',
  ml_dni: cuit.length === 11 ? cuit.slice(2, 10) : '-',
  modelo: ultimo.item_titulo || '',
  item_permalink: ultimo.item_permalink || ''
} }];

